declare enum TokenType {
    Error = 0,
    /**
     * Eot is always pushed as the last token and used by the parser to detect the endo of the file.
     */
    Eot = 1,
    /**
     * The module keyword.
     */
    Module = 2,
    /**
     * The function keyword.
     */
    Function = 3,
    /**
     * The if keyword.
     */
    If = 4,
    /**
     * The else keyword.
     */
    Else = 5,
    /**
     * The for keyword.
     */
    For = 6,
    /**
     * The let keyword.
     */
    Let = 7,
    /**
     * The assert keyword.
     */
    Assert = 8,
    /**
     * The echo keyword.
     */
    Echo = 9,
    /**
     * The each keyword.
     */
    Each = 10,
    /**
     * The use keyword.
     */
    Use = 11,
    /**
     * An identifier, represents a function, module or variable name
     */
    Identifier = 12,
    /**
     * A string literal (e.g. quoted color names)
     */
    StringLiteral = 13,
    /**
     * A number literal.
     */
    NumberLiteral = 14,
    /**
     * The true keyword.
     */
    True = 15,
    /**
     * The false keyword.
     */
    False = 16,
    /**
     * The undef keyword.
     */
    Undef = 17,
    /**
     * !
     */
    Bang = 18,
    /**
     * <
     */
    Less = 19,
    /**
     * >
     */
    Greater = 20,
    /**
     * <=
     */
    LessEqual = 21,
    /**
     * >=
     */
    GreaterEqual = 22,
    /**
     * ==
     */
    EqualEqual = 23,
    /**
     * =
     */
    Equal = 24,
    /**
     * !=
     */
    BangEqual = 25,
    /**
     * &&
     */
    AND = 26,
    /**
     * ||
     */
    OR = 27,
    Plus = 28,
    Minus = 29,
    Star = 30,
    Slash = 31,
    Percent = 32,
    Caret = 33,
    /**
     * Left parenthesis: (
     */
    LeftParen = 34,
    /**
     * Right parenthesis: )
     */
    RightParen = 35,
    /**
     * Left bracket: [
     */
    LeftBracket = 36,
    /**
     * Right bracket: ]
     */
    RightBracket = 37,
    /**
     * Left brace: {
     */
    LeftBrace = 38,
    /**
     * Right brace: }
     */
    RightBrace = 39,
    /**
     * ;
     */
    Semicolon = 40,
    /**
     * ,
     */
    Comma = 41,
    /**
     * .
     */
    Dot = 42,
    /**
     * The ? symbol
     */
    QuestionMark = 43,
    /**
     * The : symbol
     */
    Colon = 44,
    /**
     * The '#' symbol
     */
    Hash = 45,
    /**
     * The filename of an imported file e.g. '<file.scad>'
     */
    FilenameInChevrons = 46,
    /**
     * The include keyword.
     */
    Include = 47
}
export default TokenType;
